df1

# Capture prominent metrics for the comparison cell appended at publish time.
# This cell prints a single `_civic_capture=…` line that the publisher's
# Phase D parses; the line is informational and harmless on re-execution.
import json as _json

_civic_capture = {}
_civic_candidates = ["df1"]
for _name in _civic_candidates:
    _df = globals().get(_name)
    if _df is None:
        continue
    try:
        rows = int(len(_df))
        head = _df.head(5).to_dict("records")
        _civic_capture[_name] = {"rows": rows, "head": head}
    except Exception:
        continue

print("_civic_capture=" + _json.dumps(_civic_capture, default=str))

# Comparison: original vs. current (appended by Phase D at executedAt = 2026-10-16T03:41:17.210Z)
#
# Original values were captured when the notebook was first executed by the
# publisher's pipeline. On re-execution against live data, the same metrics
# are extracted from the DataFrames computed above and a per-key delta is
# printed below. See ADR-0005 §5 / Typed Standards §8.7.4 for the canonical shape.

# ORIGINAL VALUES (captured at executedAt = 2026-10-16T03:41:17.210Z)
original = {
    "df1_n_rows": 0,
}

# CURRENT VALUES (re-computed from the DataFrames above)
def recompute_key_metrics():
    current = {}
    candidates = ["df1"]
    for name in candidates:
        df = globals().get(name)
        if df is None:
            continue
        try:
            current[f"{name}_n_rows"] = int(len(df))
            head = df.head(5).to_dict("records")
            for idx, row in enumerate(head):
                for field, value in row.items():
                    current[f"{name}_row{idx}_{field}"] = value
        except Exception:
            continue
    return current

current = recompute_key_metrics()

# DELTAS
for k in original:
    if k in current:
        cur, orig = current[k], original[k]
        if isinstance(orig, (int, float)) and isinstance(cur, (int, float)):
            delta = cur - orig
        else:
            delta = (orig, cur)
        print(f"{k}: original={orig!r}, current={cur!r}, delta={delta!r}")
    else:
        print(f"{k}: original={original[k]!r}, current=<not present>, delta=<unavailable>")

function.description:
Unified Socrata open data access tool. Supports multiple operation types:
- catalog: Search the catalog for datasets matching a query on a Socrata portal
- metadata: Get detailed metadata about a specific dataset
- query: Execute a SoQL query against a dataset to fetch and filter data
- metrics: Get row count, view count, last-updated timestamps for a dataset

IMPORTANT TIPS:
1. For type=metadata and type=metrics, pass the dataset ID in "dataset_id"
2. For type=query, ALWAYS start by fetching a sample with no WHERE clause to see actual column values
3. NYC 311 data uses field names like: complaint_type, descriptor, created_date, community_board
4. Field values are case-sensitive - fetch sample data first to see exact formats

Examples:
- Search catalog: { "type": "catalog", "portal": "data.cityofnewyork.us", "query": "311 complaints" }
- Get metadata: { "type": "metadata", "portal": "data.cityofnewyork.us", "dataset_id": "erm2-nwe9" }
- Get metrics: { "type": "metrics", "portal": "data.cityofnewyork.us", "dataset_id": "erm2-nwe9" }
- Fetch sample data first: { "type": "query", "portal": "data.cityofnewyork.us", "dataset_id": "erm2-nwe9", "limit": 5 }
- Query with filter: { "type": "query", "portal": "data.cityofnewyork.us", "dataset_id": "erm2-nwe9", "select": "complaint_type, COUNT(*) as count", "group": "complaint_type", "order": "count DESC", "limit": 10 }
